{
    super();

    if (GUPPricingRuleConditionCopyLine)
    {
        GUPPricingAttributeConditionValueHelper::setPricingAttributeValueLookUpOptions(this, GUPPricingRuleConditionCopyLine.priceAttributeLink(), Checkbox_AppendValueOnLookupLine.checked());
    }
}

