public void clicked()
{
    FormDataSource fdsCaller = callerRecord.dataSource();

    super();  
    GUPPricingRule pricingRule;

    ttsbegin;

    element.refreshPricingRuleCopy();
    pricingRuleCopyHeader.clearRuleConditions();
    pricingRuleCopyLine.clearRuleConditions();
    pricingRuleCopyHeader.delete();
    pricingRuleCopyLine.delete();
    PriceDiscAdmTrans priceDiscAdmTransReset;
    select forupdate firstonly priceDiscAdmTransReset where priceDiscAdmTransReset.RecId == callerRecord.RecId;

    if (newHeaderRule)
    {
        delete_from pricingRule where pricingRule.RecId == callerRecord.PricingRuleHeader;
        priceDiscAdmTransReset.setPricingRuleReference(fieldNum(PriceDiscAdmTrans, PricingRuleHeader), 0);
    }
    if (newLineRule)
    {
        delete_from pricingRule where pricingRule.RecId == callerRecord.PricingRuleLine;
        priceDiscAdmTransReset.setPricingRuleReference(fieldNum(PriceDiscAdmTrans, PricingRuleLine), 0);
    }
    priceDiscAdmTransReset.PriceComponentCombination = callerRecord.PriceComponentCombination;
    priceDiscAdmTransReset.update();

    ttscommit;

    if (element.args().parmEnumType() == enumNum(FormDataSourceEventType)
        && element.args().parmEnum() == FormDataSourceEventType::Created)
    {
        fdsCaller.research(true);
        callerRecord.delete();
    }

    fdsCaller.research(true);
}
